  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const faqItems = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats purr for a few reasons: they often do it when they feel relaxed, but they also purr when they are anxious, healing, or trying to communicate with people and other cats.",
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, and kittens or senior cats may sleep even more. That long rest cycle is normal and helps them conserve energy for short bursts of activity.",
        },
        {
          question: "Should I feed my cat wet food, dry food, or both?",
          answer:
            "Many cats do well with a mix of wet and dry food. Wet food can help with hydration, while dry food is convenient. The best choice depends on your cat's age, health, and preferences, so check with a veterinarian for a tailored plan.",
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comforting behavior that often starts when cats are kittens. Adult cats may knead when they feel safe, content, or are settling in for a nap.",
        },
      ];

      function FAQItem(item, index) {
        const id = `faq-${index}`;
        const headingId = `${id}-heading`;
        return `
          <div class="example">
            <h2 id="${headingId}" style="margin:0">
              <button
                type="button"
                class="question"
                aria-expanded="false"
                aria-controls="${id}"
                data-disclosure
              >
                <span class="question-text">${item.question}</span>
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="${id}" role="region" aria-labelledby="${headingId}">
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function FAQApp(items) {
        return `
          <main class="page" id="main">
            <section class="shell hero" aria-labelledby="page-title">
              <p class="eyebrow">Cat care guide</p>
              <h1 id="page-title">Frequently asked questions about cats</h1>
              <p class="lede">
                Quick answers to common cat questions, presented as collapsible sections so you can skim or explore at your own pace.
              </p>
              <div class="faq" aria-label="Frequently asked questions">
                ${items.map((item, index) => FAQItem(item, index)).join("")}
              </div>
              <p class="footer-note">
                Tip: use Tab to move through the questions, then press Enter or Space to open one.
              </p>
            </section>
          </main>
        `;
      }

      function initDisclosures(root) {
        const buttons = root.querySelectorAll("[data-disclosure]");
        buttons.forEach((button) => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const expanded = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!expanded));
            panel.hidden = expanded;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
              button.focus();
            }
          });
        });
      }

      const app = document.getElementById("app");
      app.innerHTML = FAQApp(faqItems);
      initDisclosures(app);
    </script>
  </body>
